schemaSql:
CREATE TABLE drivers (
  id INTEGER PRIMARY KEY,
  name TEXT,
  city TEXT
);
CREATE TABLE riders (
  id INTEGER PRIMARY KEY,
  name TEXT
);
CREATE TABLE trips (
  id INTEGER PRIMARY KEY,
  driver_id INTEGER,
  rider_id INTEGER,
  requested_at TEXT,
  started_at TEXT,
  ended_at TEXT,
  status TEXT,
  fare REAL
);

